FAQ_H2 = ('Questions about <span style="color:#d32a37">diesel injection.</span>', 'Preguntas sobre <span style="color:#d32a37">inyección diésel.</span>', 'Perguntas sobre <span style="color:#d32a37">injeção diesel.</span>')
FAQ = [
 (('How much pressure does a common rail system run?', 'Roughly 1,600 to 2,700 bar (23,000 to 39,000 psi), depending on the system and generation. Early light duty systems sat at the low end; current Bosch and Denso systems reach the high end.'),
  ('¿Cuánta presión trabaja un sistema common rail?', 'Entre unos 1.600 y 2.700 bar (23.000 a 39.000 psi), según el sistema y la generación. Los primeros sistemas livianos estaban en el rango bajo; los sistemas Bosch y Denso actuales llegan al alto.'),
  ('Quanta pressão trabalha um sistema common rail?', 'Entre cerca de 1.600 e 2.700 bar (23.000 a 39.000 psi), conforme o sistema e a geração. Os primeiros sistemas leves ficavam na faixa baixa; os sistemas Bosch e Denso atuais chegam à faixa alta.')),
 (('Can I replace just one injector?', 'Yes, if the other injectors test good and the new injector\'s correction code is programmed into the ECU. After a high pressure pump failure, replace the whole system instead.'),
  ('¿Puedo cambiar un solo inyector?', 'Sí, si los demás inyectores pasan la prueba y el código de corrección del nuevo se programa en la ECU. Después de una falla de la bomba de alta presión, cambia el sistema completo.'),
  ('Posso trocar só um bico?', 'Sim, se os outros bicos passarem no teste e o código de correção do novo for programado na ECU. Depois da quebra da bomba de alta pressão, troque o sistema inteiro.')),
 (('What is the difference between a CP3 and a CP4 pump?', 'Both are Bosch common rail pumps. The CP3 uses three radial pistons. The CP4 uses one or two pistons driven by a cam with roller tappets, makes higher pressure and is more sensitive to fuel lubricity and water.'),
  ('¿Cuál es la diferencia entre una bomba CP3 y una CP4?', 'Ambas son bombas common rail Bosch. La CP3 usa tres pistones radiales. La CP4 usa uno o dos pistones movidos por una leva con rodillos, genera más presión y es más sensible a la lubricidad del combustible y al agua.'),
  ('Qual a diferença entre a bomba CP3 e a CP4?', 'As duas são bombas common rail Bosch. A CP3 usa três pistões radiais. A CP4 usa um ou dois pistões acionados por um came com roletes, gera mais pressão e é mais sensível à lubricidade do combustível e à água.')),
 (('What is ISO 4113 fluid used for?', 'It is the standard test fluid for diesel injector and pump test benches. Its fixed viscosity and density make flow measurements repeatable from one test to the next.'),
  ('¿Para qué sirve el fluido ISO 4113?', 'Es el fluido de prueba estándar para bancos de inyectores y bombas diésel. Su viscosidad y densidad fijas hacen que las mediciones de caudal se repitan de una prueba a otra.'),
  ('Para que serve o fluido ISO 4113?', 'É o fluido de teste padrão para bancadas de bicos e bombas diesel. A viscosidade e a densidade fixas fazem as medições de vazão se repetirem de um teste para outro.')),
 (('Does Maxzz Diesel sell to repair shops?', 'Yes. Maxzz Diesel sells wholesale to rebuilders, injection labs, distributors, repair shops and fleets in North America and Latin America. Prices are by quote or through the wholesale login.'),
  ('¿Maxzz Diesel vende a talleres?', 'Sí. Maxzz Diesel vende al por mayor a reconstructores, laboratorios diésel, distribuidores, talleres y flotas en Norteamérica y Latinoamérica. Los precios son por cotización o con el acceso mayorista.'),
  ('A Maxzz Diesel vende para oficinas?', 'Sim. A Maxzz Diesel vende no atacado para retíficas, laboratórios diesel, distribuidores, oficinas e frotas na América do Norte e na América Latina. Os preços são por cotação ou pelo acesso de atacado.')),
]

